<?php
declare(strict_types=1);
require_once __DIR__.'/../_admin.php';header('Cache-Control: no-store');$input=adminMethod(['GET','POST']);$pdo=Database::getInstance();[$session,$role]=requireAdmin($pdo,$input);requireAdminRole($role,['super_admin','reviewer'],'manage account levels');
$defaults=[['individual',1,'Starter','Email verified',50000,100000,25000,50000,50000,100000,0,1.5,0,0,0],['individual',2,'Verified','Identity verified',250000,500000,150000,300000,250000,500000,500000,1.0,1,1,0],['individual',3,'Advanced','Enhanced verification',1000000,2000000,750000,1500000,1000000,2000000,2000000,.75,1,1,1],['business',1,'Business starter','Business profile approved',500000,1000000,250000,500000,500000,1000000,0,1.5,0,1,0],['business',2,'Business verified','Business verification approved',2000000,5000000,1500000,3000000,2000000,5000000,5000000,1,1,1,1]];
foreach($defaults as $d){$q=$pdo->prepare('SELECT id FROM admin_account_levels WHERE account_type=? AND rank=?');$q->execute([$d[0],$d[1]]);if(!$q->fetch()){$pdo->prepare('INSERT INTO admin_account_levels(uuid,account_type,rank,name,requirement,deposit_single,deposit_daily,withdraw_single,withdraw_daily,transfer_single,transfer_daily,max_balance,fee_percent,api_access,payment_links,bulk_transfers) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([generateUUID(),...$d]);}}
if($_SERVER['REQUEST_METHOD']==='POST'){requireAdminRole($role,['super_admin'],'update account levels');if(($input['action']??'')!=='update')jsonResponse(['success'=>false,'error'=>'Unknown action.'],422);$uuid=(string)($input['uuid']??'');$fields=['name','deposit_single','deposit_daily','withdraw_single','withdraw_daily','transfer_single','transfer_daily','max_balance','fee_percent','api_access','payment_links','bulk_transfers'];$set=[];$values=[];foreach($fields as $f){$set[]="$f=?";$values[]=$input[$f]??null;}$values[]=(int)$session['admin']['id'];$values[]=$uuid;$stmt=$pdo->prepare('UPDATE admin_account_levels SET '.implode(',',$set).',updated_by=?,updated_at=UTC_TIMESTAMP() WHERE uuid=?');$stmt->execute($values);if(!$stmt->rowCount())jsonResponse(['success'=>false,'error'=>'Level not found.'],404);$pdo->prepare('INSERT INTO admin_level_changes(level_uuid,admin_user_id,summary) VALUES(?,?,?)')->execute([$uuid,(int)$session['admin']['id'],'Level limits and features updated']);adminAudit($pdo,(int)$session['admin']['id'],'admin.level_updated','account_level',$uuid);jsonResponse(['success'=>true,'message'=>'Level saved.']);}
$levels=$pdo->query("SELECT l.*,COALESCE((SELECT COUNT(*) FROM users u WHERE u.account_type=CASE WHEN l.account_type='individual' THEN 'individual' ELSE 'business' END AND u.kyc_tier=l.rank),0) users_count FROM admin_account_levels l ORDER BY l.account_type,l.rank")->fetchAll();$summary=$pdo->query("SELECT COUNT(*) users,SUM(status='pending_verification') pending_reviews,SUM(kyc_tier>=2) api_users FROM users")->fetch()?:[];$changes=$pdo->query("SELECT c.created_at,c.summary,l.name level_name,COALESCE(a.full_name,'System') admin_name FROM admin_level_changes c JOIN admin_account_levels l ON l.uuid=c.level_uuid LEFT JOIN admin_users a ON a.id=c.admin_user_id ORDER BY c.created_at DESC LIMIT 25")->fetchAll();jsonResponse(['success'=>true,'levels'=>$levels,'summary'=>['users'=>(int)($summary['users']??0),'pending_reviews'=>(int)($summary['pending_reviews']??0),'api_users'=>(int)($summary['api_users']??0)],'changes'=>$changes]);
